internal fun advancedProCopy(language: AppLanguage, english: String): String? {
    if (language == AppLanguage.EN) return english
    return advancedProStrings[english]?.getOrNull(language.ordinal)
}

internal fun advancedProEnglishKeys(): Set<String> = advancedProStrings.keys
